import { notFound, redirect } from "next/navigation";
import { headers } from "next/headers";
import { CYRUS_ADMIN_HOST_HEADER } from "@/lib/cyrus/bridge/config";
import { realUser } from "@/lib/auth";
import { isPreviewUser } from "@/lib/preview-access";
import { visibleCyrusTabs } from "@/lib/cyrus/admin/perms";
import { cyrusModsPublicEnabled } from "@/lib/cyrus-mods/gate";
import { SubTabs } from "@/components/admin/SubTabs";
import { Badge } from "@/components/ui/primitives";

export const dynamic = "force-dynamic";

/**
 * /admin/cyrus: operating Cyrus (staff side). URL-only while Cyrus is in private preview (no
 * admin-nav entry, like /admin/mod-builder): the real account must be staff (admin layout) AND on
 * the "modbuilder" preview list, else 404. Each tab gates itself again with requireCyrusAdmin(tab),
 * and only the tabs the role may open are listed (lib/cyrus/admin/perms.ts).
 */
export default async function CyrusAdminLayout({ children }: { children: React.ReactNode }) {
  const user = await realUser();
  if (!user || !(await isPreviewUser(user, "modbuilder"))) notFound();
  const tabs = visibleCyrusTabs(user.role);
  // r51: on the secret Cyrus admin host there is no rest of /admin to fall back to
  if (!tabs.length) { if ((await headers()).get(CYRUS_ADMIN_HOST_HEADER) === "1") notFound(); redirect("/admin"); }
  const launched = await cyrusModsPublicEnabled();
  return (
    <div className="min-w-0" data-cyrus-admin>
      <div className="mb-3 flex flex-wrap items-end justify-between gap-3">
        <div className="min-w-0">
          <h1 className="page-title">Cyrus</h1>
          <p className="mt-1 text-sm text-slate-400">Operate the AI mod studio: builds, tokens, games and models, community, safety, and every admin action taken here.</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Badge tone="brand">private preview</Badge>
          {launched ? <Badge tone="green">community: public</Badge> : <Badge tone="slate">community: preview only</Badge>}
        </div>
      </div>
      <SubTabs items={tabs.map((t) => ({ label: t.label, href: t.href }))} />
      <div className="mt-5 min-w-0">{children}</div>
    </div>
  );
}
// Cyrus admin (/admin/cyrus): who may see each tab and take each action. Pure decisions (server-side:
// it reuses lib/rbac.ts, which imports auth). Unit-tested in test/cyrus-admin.test.ts.
//
// Every tab and every write maps to one admin Area (lib/rbac.ts), so the Cyrus screens follow the
// same role model as the rest of the admin portal:
//   fleet    (ADMIN)            builds, service health, AI cost, cancel / re-run
//   billing  (BILLING + ADMIN)  token balances, grants, refunds, comps
//   support  (SUPPORT + ADMIN)  community moderation (reports, hidden posts, takedowns, suspensions)
//   platform (ADMIN)            game status, networking review + kill switch, Cyrus settings
// On top of the role, the whole section is behind the "modbuilder" private-preview allowlist
// (lib/preview-access.ts), like /admin/mod-builder and /admin/cyrus-tokens, until Cyrus launches.
import type { Role } from "@prisma/client";
import { canAccess, type Area } from "../../rbac";

export const CYRUS_ADMIN_BASE = "/admin/cyrus";

export type CyrusAdminTab = "overview" | "builds" | "users" | "cost" | "reconcile" | "games" | "community" | "library" | "storage" | "learning" | "notify" | "flags" | "audit";

export const CYRUS_ADMIN_TABS: { id: CyrusAdminTab; label: string; href: string; area: Area }[] = [
  { id: "overview", label: "Overview", href: CYRUS_ADMIN_BASE, area: "fleet" },
  { id: "builds", label: "Builds", href: `${CYRUS_ADMIN_BASE}/builds`, area: "fleet" },
  { id: "users", label: "Users & tokens", href: `${CYRUS_ADMIN_BASE}/users`, area: "billing" },
  { id: "cost", label: "Cost", href: `${CYRUS_ADMIN_BASE}/cost`, area: "billing" },
  { id: "reconcile", label: "Reconciliation", href: `${CYRUS_ADMIN_BASE}/reconcile`, area: "billing" },
  { id: "games", label: "Games & models", href: `${CYRUS_ADMIN_BASE}/games`, area: "platform" },
  { id: "community", label: "Community", href: `${CYRUS_ADMIN_BASE}/community`, area: "support" },
  { id: "library", label: "Library & safety", href: `${CYRUS_ADMIN_BASE}/library`, area: "fleet" },
  // r51: total storage across accounts, mods, packs, the library, backups and disks (ADMIN: fleet)
  { id: "storage", label: "Storage", href: `${CYRUS_ADMIN_BASE}/storage`, area: "fleet" },
  // learning loop (2026-10-12): read-only signals + candidate list from the mining job output (CYRUS_LEARNING, off by default)
  { id: "learning", label: "Learning", href: `${CYRUS_ADMIN_BASE}/learning`, area: "fleet" },
  { id: "notify", label: "Notifications", href: `${CYRUS_ADMIN_BASE}/notify`, area: "platform" },
  { id: "flags", label: "Flags & kill switches", href: `${CYRUS_ADMIN_BASE}/flags`, area: "platform" },
  { id: "audit", label: "Audit & settings", href: `${CYRUS_ADMIN_BASE}/audit`, area: "platform" },
];

/** Every write the Cyrus admin can make, with the Area it needs. */
export const CYRUS_ADMIN_ACTIONS = {
  "build.cancel": "fleet",
  "build.rerun": "fleet",
  "build.refund": "billing",
  "build.refund.undo": "billing",
  "tokens.grant": "billing",
  "tokens.revoke": "billing",
  "tokens.comp": "billing",
  "user.suspend": "support",
  "user.unsuspend": "support",
  "report.hide": "support",
  "report.dismiss": "support",
  "post.unhide": "support",
  "page.takedown": "support",
  "page.restore": "support",
  "network.review": "platform",
  "network.killswitch": "platform",
  "game.status": "platform",
  "setting.set": "platform",
  // r40 admin core
  "user.viewas": "support", // read-only staff view (lib/cyrus/admin/viewas.ts), not impersonation
  "user.ban": "support",
  "user.unban": "support",
  "user.ban.nxeon": "platform",
  "user.unban.nxeon": "platform",
  "user.gdpr.export": "platform",
  "user.gdpr.erase": "platform",
  // r40 library moderation (the Library & safety tab is ADMIN: fleet)
  "library.release": "fleet",
  "library.reject": "fleet",
  "library.takedown": "fleet",
  "library.restore": "fleet",
  "library.reports.dismiss": "fleet",
  "library.lists": "fleet",
  "legal.case": "fleet",
  // r40 flags & kill switches
  "flag.launch": "platform",
  "flag.kill": "platform",
  // r40 reconciliation
  "reconcile.wallet": "billing",
  "webhook.replay": "platform",
  // r40 notifications
  "notify.sender": "platform",
  // r51 storage
  "storage.export": "fleet",
} as const satisfies Record<string, Area>;

export type CyrusAdminAction = keyof typeof CYRUS_ADMIN_ACTIONS;

export const isCyrusAdminAction = (v: unknown): v is CyrusAdminAction => typeof v === "string" && v in CYRUS_ADMIN_ACTIONS;

export function canCyrusAdmin(role: Role, action: CyrusAdminAction): boolean {
  return canAccess(role, CYRUS_ADMIN_ACTIONS[action]);
}

export function canSeeCyrusTab(role: Role, tab: CyrusAdminTab): boolean {
  const t = CYRUS_ADMIN_TABS.find((x) => x.id === tab);
  return !!t && canAccess(role, t.area);
}

export function visibleCyrusTabs(role: Role) {
  return CYRUS_ADMIN_TABS.filter((t) => canAccess(role, t.area));
}

/** The first tab a role may open (null = none: the section is not for this role). */
export function landingCyrusTab(role: Role) {
  return visibleCyrusTabs(role)[0] ?? null;
}
