// Cyrus token economy: every tunable number, as admin Settings (`cyrus_tok_*`).
//
// Pure + client-safe except `loadTokenConfig` (DB read, server only, dynamic import).
// Defaults are the recommended numbers from /root/agent-notes/cyrus-economy/ECONOMY.md;
// docs/DOCUMENTATION.md "Cyrus token economy" explains each one. A Setting row overrides
// its default; a blank or unparseable value falls back to the default (never to 0), so
// a fat-fingered admin edit can't silently make builds free or grants huge.
import type { CyrusModelId } from "../models";

export const TOKEN_TIERS = ["free", "katara", "saka", "all"] as const;
export type TokenTier = (typeof TOKEN_TIERS)[number];
export const PLAN_TIERS = ["katara", "saka", "all"] as const;
export type PlanTier = (typeof PLAN_TIERS)[number];
export const isPlanTier = (v: unknown): v is PlanTier => typeof v === "string" && (PLAN_TIERS as readonly string[]).includes(v);

export type Complexity = "simple" | "standard" | "complex";
export type ReserveTable = Record<CyrusModelId, Record<Complexity, [number, number]>>;

export const DEFAULT_RESERVE_TABLE: ReserveTable = {
  katara: { simple: [30, 70], standard: [60, 140], complex: [100, 240] },
  saka: { simple: [35, 100], standard: [60, 220], complex: [110, 400] },
  yakko: { simple: [100, 250], standard: [200, 500], complex: [400, 1000] },
};

export const CYRUS_TOKEN_DEFAULTS = {
  // --- Launch / gate ---
  /** false = only private-preview accounts (lib/preview-access "modbuilder") earn, see or spend tokens. */
  cyrus_tok_live: "false",
  /** true = a build needs tokens and the plan's model unlock. false = tokens are tracked but never block. */
  cyrus_tok_enforce: "true",
  /** Show "Includes N Cyrus tokens" on game checkout (still preview-only until cyrus_tok_live). */
  cyrus_tok_checkout_line: "true",

  // --- What a token is worth ---
  /** Tokens charged per 1 USD of measured AI cost (build service costUsd). 500 = 1 token per $0.002. */
  cyrus_tok_tokens_per_usd: "500",
  cyrus_tok_mult_katara: "1",
  cyrus_tok_mult_saka: "1",
  /** Yakko premium: heavier variance, holds a build slot ~2x longer. */
  cyrus_tok_mult_yakko: "1.25",
  /** Floor for any build that reached the AI. */
  cyrus_tok_min_spend: "5",
  /** Per model x complexity [typical low, high] tokens; high is what a build reserves. JSON. */
  cyrus_tok_reserve_table: JSON.stringify(DEFAULT_RESERVE_TABLE),

  // --- Failure / abuse ---
  cyrus_tok_charge_refused: "true",
  cyrus_tok_charge_cancelled: "true",
  /** % of the actual cost charged for a build that failed on our side (compile, timeout, outage). */
  cyrus_tok_failed_charge_pct: "0",
  /** Our-side failures that are free per rolling window; after that they are charged in full. */
  cyrus_tok_free_failures: "3",
  cyrus_tok_free_failures_days: "7",
  /** Max tokens reserved+spent per rolling 24 h. */
  cyrus_tok_daily_spend_cap: "5000",
  cyrus_tok_new_account_days: "7",
  cyrus_tok_new_account_daily_cap: "1000",
  /** Below this the UI shows the low-balance state. */
  cyrus_tok_low_balance: "100",
  /** One-time starter tokens for an account that has never held any (verified email, economy live). 0 turns it off. */
  cyrus_tok_starter: "70",
  cyrus_tok_starter_days: "30",

  // --- Game-server grants: amount = clamp(round5(base + perUsd * monthly $), min, max) ---
  cyrus_tok_grant_initial_base: "100",
  cyrus_tok_grant_initial_per_usd: "16",
  cyrus_tok_grant_initial_min: "150",
  cyrus_tok_grant_initial_max: "750",
  cyrus_tok_grant_renew_base: "25",
  cyrus_tok_grant_renew_per_usd: "6",
  cyrus_tok_grant_renew_min: "40",
  cyrus_tok_grant_renew_max: "300",
  /** A prepaid N-month term is granted per month, up to this many months. */
  cyrus_tok_grant_term_months_cap: "12",
  /** Server-grant lots expire after this many days (or the term + 30 d, whichever is longer). */
  cyrus_tok_grant_expiry_days: "90",
  /** Initial grants per account per rolling 30 days (farming many cheap servers). */
  cyrus_tok_grant_max_initial_per_30d: "3",
  /** Max unexpired server-grant tokens one account can hold. */
  cyrus_tok_grant_balance_cap: "3000",
  // r41 (PLACEHOLDERS pending owner decision, see TOKEN_PLACEHOLDER_KEYS + OWNER-ACTIONS "r41"):
  /** Which Nxeon servers earn tokens: cyrus_games (games Cyrus builds for) | all_game_servers | all_servers. */
  cyrus_tok_grant_scope: "cyrus_games",
  /** Lifetime tokens one server can ever earn (initial + every renewal). 0 = no per-server cap. */
  cyrus_tok_grant_per_server_cap: "2000",
  /** A server deleted within this many days of its first grant gives back that server's unspent tokens. 0 = never. */
  cyrus_tok_grant_clawback_days: "14",

  // --- Plans (Stripe subscriptions, renew monthly, tokens stack) ---
  cyrus_tok_plan_katara_tokens: "750",
  cyrus_tok_plan_saka_tokens: "3500",
  cyrus_tok_plan_all_tokens: "10000",
  /** Display prices + the proration rate. The real charge is the Stripe Price. */
  cyrus_tok_plan_katara_cents: "499",
  cyrus_tok_plan_saka_cents: "1999",
  cyrus_tok_plan_all_cents: "4999",
  /** r41: while_active = unspent plan tokens roll over month to month for as long as the plan stays active (no age
   *  limit); age = each month's tokens last cyrus_tok_plan_rollover_months (the pre-r41 rule). */
  cyrus_tok_plan_rollover_mode: "while_active",
  /** Rollover cap (r41, PLACEHOLDER): plan tokens held never exceed this many months of the plan's tokens (the excess of
   *  a new month is not credited; nothing already held is taken). 0 = no cap. */
  cyrus_tok_plan_rollover_cap_months: "0",
  /** mode=age only: each month's plan tokens last this many months (so at most this many months stack). */
  cyrus_tok_plan_rollover_months: "3",
  /** r41 (PLACEHOLDER): what happens to plan tokens when the plan ends. freeze_then_expire = kept but not spendable,
   *  back if they resubscribe within the grace, gone after it; grace_then_expire = usable during the grace, then gone;
   *  expire = gone at the period end. */
  cyrus_tok_plan_lapse_rule: "freeze_then_expire",
  /** The lapse grace in days (both grace rules). */
  cyrus_tok_plan_cancel_grace_days: "30",
  /** A failed renewal keeps the unlock this many days past the period end while Stripe retries. */
  cyrus_tok_plan_past_due_grace_days: "3",
  /** Price id overrides; blank = find the price by lookup_key (scripts/cyrus-tokens-stripe-setup.ts). */
  cyrus_tok_price_katara: "",
  cyrus_tok_price_saka: "",
  cyrus_tok_price_all: "",

  // --- One-off top-ups ---
  cyrus_tok_topup_enabled: "true",
  cyrus_tok_topup_tokens_per_usd: "120",
  cyrus_tok_topup_min_cents: "500",
  cyrus_tok_topup_max_cents: "10000",
  cyrus_tok_topup_expiry_days: "365",
  /** true = only accounts with a paid game server or plan may buy a top-up. */
  cyrus_tok_topup_requires_paid: "false",

  // --- Admin ---
  cyrus_tok_admin_grant_expiry_days: "365",
} as const;

export type TokenSettingKey = keyof typeof CYRUS_TOKEN_DEFAULTS;
/** Settings whose default is a placeholder until the owner decides (shown as such in /admin/cyrus-tokens). */
export const TOKEN_PLACEHOLDER_KEYS: readonly TokenSettingKey[] = [
  "cyrus_tok_grant_scope", "cyrus_tok_grant_per_server_cap", "cyrus_tok_grant_clawback_days",
  "cyrus_tok_grant_initial_base", "cyrus_tok_grant_initial_per_usd", "cyrus_tok_grant_initial_min", "cyrus_tok_grant_initial_max",
  "cyrus_tok_grant_renew_base", "cyrus_tok_grant_renew_per_usd", "cyrus_tok_grant_renew_min", "cyrus_tok_grant_renew_max",
  "cyrus_tok_plan_rollover_cap_months", "cyrus_tok_plan_lapse_rule", "cyrus_tok_plan_cancel_grace_days",
];
/** Text settings with a fixed set of values (anything else = the default). */
export const TOKEN_ENUMS = {
  cyrus_tok_grant_scope: ["cyrus_games", "all_game_servers", "all_servers"],
  cyrus_tok_plan_rollover_mode: ["while_active", "age"],
  cyrus_tok_plan_lapse_rule: ["freeze_then_expire", "grace_then_expire", "expire"],
} as const;
export type GrantScope = (typeof TOKEN_ENUMS.cyrus_tok_grant_scope)[number];
export type RolloverMode = (typeof TOKEN_ENUMS.cyrus_tok_plan_rollover_mode)[number];
export type LapseRule = (typeof TOKEN_ENUMS.cyrus_tok_plan_lapse_rule)[number];
export const TOKEN_SETTING_KEYS = Object.keys(CYRUS_TOKEN_DEFAULTS) as TokenSettingKey[];

export type TokenConfig = {
  live: boolean;
  enforce: boolean;
  checkoutLine: boolean;
  tokensPerUsd: number;
  mult: Record<CyrusModelId, number>;
  minSpend: number;
  reserve: ReserveTable;
  chargeRefused: boolean;
  chargeCancelled: boolean;
  failedChargePct: number;
  freeFailures: number;
  freeFailuresDays: number;
  dailyCap: number;
  newAccountDays: number;
  newAccountDailyCap: number;
  lowBalance: number;
  starterTokens: number;
  starterDays: number;
  grant: {
    initial: { base: number; perUsd: number; min: number; max: number };
    renew: { base: number; perUsd: number; min: number; max: number };
    termMonthsCap: number;
    expiryDays: number;
    maxInitialPer30d: number;
    balanceCap: number;
    scope: GrantScope;
    perServerCap: number;
    clawbackDays: number;
  };
  plan: {
    tokens: Record<PlanTier, number>;
    cents: Record<PlanTier, number>;
    rolloverMonths: number;
    rolloverMode: RolloverMode;
    rolloverCapMonths: number;
    lapseRule: LapseRule;
    cancelGraceDays: number;
    pastDueGraceDays: number;
    priceIds: Record<PlanTier, string>;
  };
  topup: { enabled: boolean; tokensPerUsd: number; minCents: number; maxCents: number; expiryDays: number; requiresPaid: boolean };
  adminGrantExpiryDays: number;
};

function num(raw: string | undefined, def: string, { min = 0, max = Number.MAX_SAFE_INTEGER } = {}): number {
  const n = Number(raw);
  const d = Number(def);
  if (raw === undefined || raw.trim() === "" || !Number.isFinite(n)) return d;
  return Math.min(max, Math.max(min, n));
}
function bool(raw: string | undefined, def: string): boolean {
  const v = (raw ?? def).trim().toLowerCase();
  return v === "true" || v === "1" || v === "on";
}

function parseReserve(raw: string | undefined): ReserveTable {
  const out: ReserveTable = JSON.parse(JSON.stringify(DEFAULT_RESERVE_TABLE));
  if (!raw) return out;
  try {
    const j = JSON.parse(raw) as Record<string, Record<string, unknown>>;
    for (const m of Object.keys(out) as CyrusModelId[]) {
      for (const c of ["simple", "standard", "complex"] as Complexity[]) {
        const v = j?.[m]?.[c];
        if (Array.isArray(v) && v.length === 2 && v.every((x) => Number.isFinite(Number(x)) && Number(x) > 0)) {
          const lo = Math.round(Number(v[0]));
          const hi = Math.max(lo, Math.round(Number(v[1])));
          out[m][c] = [lo, hi];
        }
      }
    }
  } catch { /* keep defaults */ }
  return out;
}

/** Pure: stored Setting values (any subset) -> typed config. Unit-tested. */
export function parseTokenConfig(stored: Partial<Record<string, string>>): TokenConfig {
  const D = CYRUS_TOKEN_DEFAULTS;
  const g = (k: TokenSettingKey) => stored[k];
  const n = (k: TokenSettingKey, o?: { min?: number; max?: number }) => num(g(k), D[k], o);
  const b = (k: TokenSettingKey) => bool(g(k), D[k]);
  const e = <K extends keyof typeof TOKEN_ENUMS>(k: K): (typeof TOKEN_ENUMS)[K][number] => {
    const v = (g(k) ?? "").trim();
    return ((TOKEN_ENUMS[k] as readonly string[]).includes(v) ? v : D[k]) as (typeof TOKEN_ENUMS)[K][number];
  };
  return {
    live: b("cyrus_tok_live"),
    enforce: b("cyrus_tok_enforce"),
    checkoutLine: b("cyrus_tok_checkout_line"),
    tokensPerUsd: n("cyrus_tok_tokens_per_usd", { min: 1, max: 100000 }),
    mult: {
      katara: n("cyrus_tok_mult_katara", { min: 0.1, max: 20 }),
      saka: n("cyrus_tok_mult_saka", { min: 0.1, max: 20 }),
      yakko: n("cyrus_tok_mult_yakko", { min: 0.1, max: 20 }),
    },
    minSpend: Math.round(n("cyrus_tok_min_spend", { max: 10000 })),
    reserve: parseReserve(g("cyrus_tok_reserve_table")),
    chargeRefused: b("cyrus_tok_charge_refused"),
    chargeCancelled: b("cyrus_tok_charge_cancelled"),
    failedChargePct: n("cyrus_tok_failed_charge_pct", { max: 100 }),
    freeFailures: Math.round(n("cyrus_tok_free_failures", { max: 1000 })),
    freeFailuresDays: Math.round(n("cyrus_tok_free_failures_days", { min: 1, max: 90 })),
    dailyCap: Math.round(n("cyrus_tok_daily_spend_cap", { min: 1 })),
    newAccountDays: Math.round(n("cyrus_tok_new_account_days", { max: 365 })),
    newAccountDailyCap: Math.round(n("cyrus_tok_new_account_daily_cap", { min: 1 })),
    lowBalance: Math.round(n("cyrus_tok_low_balance")),
    starterTokens: Math.round(n("cyrus_tok_starter", { max: 100000 })),
    starterDays: Math.round(n("cyrus_tok_starter_days", { min: 1, max: 365 })),
    grant: {
      initial: {
        base: n("cyrus_tok_grant_initial_base"), perUsd: n("cyrus_tok_grant_initial_per_usd"),
        min: n("cyrus_tok_grant_initial_min"), max: n("cyrus_tok_grant_initial_max"),
      },
      renew: {
        base: n("cyrus_tok_grant_renew_base"), perUsd: n("cyrus_tok_grant_renew_per_usd"),
        min: n("cyrus_tok_grant_renew_min"), max: n("cyrus_tok_grant_renew_max"),
      },
      termMonthsCap: Math.round(n("cyrus_tok_grant_term_months_cap", { min: 1, max: 36 })),
      expiryDays: Math.round(n("cyrus_tok_grant_expiry_days", { min: 1, max: 3650 })),
      maxInitialPer30d: Math.round(n("cyrus_tok_grant_max_initial_per_30d", { max: 1000 })),
      balanceCap: Math.round(n("cyrus_tok_grant_balance_cap")),
      scope: e("cyrus_tok_grant_scope"),
      perServerCap: Math.round(n("cyrus_tok_grant_per_server_cap")),
