let cache: { cfg: TokenConfig; at: number } | null = null;

/** Server only: the live config (30 s in-process cache; `fresh` bypasses it). */
export async function loadTokenConfig(fresh = false): Promise<TokenConfig> {
  if (!fresh && cache && Date.now() - cache.at < 30_000) return cache.cfg;
  const { getHost } = await import("../host");
  const cfg = parseTokenConfig(await getHost().settings.readStoredPrefix("cyrus_tok_"));
  cache = { cfg, at: Date.now() };
  return cfg;
}

export function clearTokenConfigCache() { cache = null; }
// Cyrus plans: "how many mods or edits can I make with this?" (pure, client-safe, unit-tested).
//
// Computed ONLY from the live cost table the economy already uses, never from hardcoded counts:
//  - the reserve table (`cyrus_tok_reserve_table`, lib/cyrus/tokens/config.ts): per model and size,
//    [typical, high] tokens a build spends, measured from real builds (ECONOMY.md section 1);
//  - CHANGE_COST_FACTOR (lib/cyrus/estimate.ts): an edit costs about that share of a fresh build.
// A range is [tokens / high, tokens / typical], rounded so it never promises more than the table.
// The UI always labels it an estimate ("depends on size").
import { CHANGE_COST_FACTOR } from "../estimate";
import type { CyrusModelId } from "../models";
import type { ReserveTable } from "./config";

export type CountRange = [number, number];
export type PlanModelEstimate = {
  model: CyrusModelId;
  /** small mods ("simple": a command, a message, a drop table) */
  small: CountRange;
  /** typical mods ("standard": menus, saved data, an economy) */
  typical: CountRange;
  /** edits / refinements of a small mod */
  edits: CountRange;
};

/** Round a count down to something readable: exact below 20, then to 5s, then to 10s. */
export function niceDown(n: number): number {
  const v = Math.max(0, Math.floor(n));
  if (v < 20) return v;
  if (v < 100) return Math.floor(v / 5) * 5;
  return Math.floor(v / 10) * 10;
}

/** How many builds of a [typical, high] token range fit in `tokens`. */
export function countRange(tokens: number, range: readonly [number, number], factor = 1): CountRange {
  const lo = Math.max(1, range[0] * factor);
  const hi = Math.max(lo, range[1] * factor);
  const a = niceDown(tokens / hi);
  const b = niceDown(tokens / lo);
  return [Math.min(a, b), b];
}

export function planModelEstimate(tokens: number, model: CyrusModelId, reserve: ReserveTable): PlanModelEstimate {
  const t = reserve[model] ?? reserve.saka;
  return {
    model,
    small: countRange(tokens, t.simple),
    typical: countRange(tokens, t.standard),
    edits: countRange(tokens, t.simple, CHANGE_COST_FACTOR),
  };
}

/** Per unlocked model, best model first (a plan's headline is its top model). */
export function planEstimates(tokens: number, models: readonly CyrusModelId[], reserve: ReserveTable): PlanModelEstimate[] {
  const order: CyrusModelId[] = ["yakko", "saka", "katara"];
  return order.filter((m) => models.includes(m)).map((m) => planModelEstimate(tokens, m, reserve));
}

/** "20 to 35" / "4" / "less than 1". */
export function fmtCount([a, b]: CountRange): string {
  if (b <= 0) return "less than 1";
  if (a === b) return `${a}`;
  return `${a} to ${b}`;
}

/** One plain sentence, e.g. "about 10 to 25 small mods or 13 to 31 edits on Katara". */
export function planEstimateLine(e: PlanModelEstimate, modelName: string): string {
  return `about ${fmtCount(e.small)} small mods or ${fmtCount(e.edits)} edits on ${modelName}`;
}

// Cyrus admin r40: cost governance. PURE (client-safe); unit-tested in test/cyrus-admin-r40.test.ts.
// Every figure is computed from rows the caller passes in (ModBuild.costUsd, the AI calls in ModBuild.result, token
// ledger payments, CyrusPlan rows). Plan prices are INPUTS (the cyrus_tok_plan_*_cents settings); caps and alert
// thresholds are the owner's settings and default to 0 = off, so nothing here invents a number.

export const COST_SETTINGS = {
  userDailyCapUsd: "cyrus_cost_user_daily_cap_usd",
  userMonthlyCapUsd: "cyrus_cost_user_monthly_cap_usd",
  platformDailyCapUsd: "cyrus_cost_platform_daily_cap_usd",
  alertPlatformDailyUsd: "cyrus_cost_alert_platform_daily_usd",
  alertUserDailyUsd: "cyrus_cost_alert_user_daily_usd",
} as const;
export type CostCaps = { -readonly [K in keyof typeof COST_SETTINGS]: number };

/** Stored strings -> caps (blank, bad or negative = 0 = off). */
export function parseCostCaps(stored: Record<string, string | undefined>): CostCaps {
  const out = {} as CostCaps;
  for (const [k, key] of Object.entries(COST_SETTINGS) as [keyof CostCaps, string][]) {
    const n = Number(stored[key]);
    out[k] = Number.isFinite(n) && n > 0 ? Math.min(n, 1_000_000) : 0;
  }
  return out;
}

export const anyCap = (c: CostCaps) => c.userDailyCapUsd > 0 || c.userMonthlyCapUsd > 0 || c.platformDailyCapUsd > 0;

export type CapDecision = { ok: true } | { ok: false; status: 429 | 503; code: "user_daily_spend_cap" | "user_monthly_spend_cap" | "platform_spend_cap"; error: string };

/** Should a NEW build start, given what AI already cost today / this month? (running builds are never stopped) */
export function spendCapDecision(i: { caps: CostCaps; userTodayUsd: number; userMonthUsd: number; platformTodayUsd: number }): CapDecision {
  const c = i.caps;
  if (c.platformDailyCapUsd > 0 && i.platformTodayUsd >= c.platformDailyCapUsd) return { ok: false, status: 503, code: "platform_spend_cap", error: "Cyrus has reached today's building capacity. Please try again tomorrow (UTC)." };
  if (c.userDailyCapUsd > 0 && i.userTodayUsd >= c.userDailyCapUsd) return { ok: false, status: 429, code: "user_daily_spend_cap", error: "You have reached today's build limit for your account. It resets at midnight UTC." };
  if (c.userMonthlyCapUsd > 0 && i.userMonthUsd >= c.userMonthlyCapUsd) return { ok: false, status: 429, code: "user_monthly_spend_cap", error: "You have reached this month's build limit for your account. Contact support if you need more." };
  return { ok: true };
}

export const utcDayStart = (d: Date) => new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
export const utcMonthStart = (d: Date) => new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), 1));

// ---------------------------------------------------------------------------
// Spend by user / by underlying model
// ---------------------------------------------------------------------------

export type CostBuild = { userId: string; costUsd: number; createdAt: Date };
export type UserSpend = { userId: string; d1: number; d7: number; d30: number; builds30: number; meanDaily30: number };

export function spendByUser(rows: CostBuild[], now: Date): UserSpend[] {
  const DAY = 86_400_000, t = now.getTime();
  const by = new Map<string, UserSpend>();
  for (const r of rows) {
    const age = t - r.createdAt.getTime();
    if (age < 0 || age > 30 * DAY) continue;
    const u = by.get(r.userId) ?? { userId: r.userId, d1: 0, d7: 0, d30: 0, builds30: 0, meanDaily30: 0 };
    const c = Number.isFinite(r.costUsd) ? r.costUsd : 0;
    u.d30 += c; u.builds30++;
    if (age <= 7 * DAY) u.d7 += c;
    if (age <= DAY) u.d1 += c;
    by.set(r.userId, u);
  }
  return [...by.values()].map((u) => ({ ...u, meanDaily30: u.d30 / 30 })).sort((a, b) => b.d30 - a.d30);
}

export type CallRow = { model: string; costUsd: number | null; input?: number | null; output?: number | null };
export type ModelSpend = { model: string; calls: number; costUsd: number; unpriced: number; input: number; output: number };

export function spendByModel(calls: CallRow[]): ModelSpend[] {
  const by = new Map<string, ModelSpend>();
  for (const c of calls) {
    const m = String(c.model || "unknown").replace(/-\d{8}$/, "").slice(0, 60);
    const s = by.get(m) ?? { model: m, calls: 0, costUsd: 0, unpriced: 0, input: 0, output: 0 };
    s.calls++;
    if (typeof c.costUsd === "number" && Number.isFinite(c.costUsd)) s.costUsd += c.costUsd; else s.unpriced++;
    s.input += Number(c.input) || 0; s.output += Number(c.output) || 0;
    by.set(m, s);
  }
  return [...by.values()].sort((a, b) => b.costUsd - a.costUsd);
}

/** The AI calls recorded in ModBuild.result (tolerant: unknown shapes give nothing). */
export function callsOfResult(result: unknown): CallRow[] {
  const ai = result && typeof result === "object" ? (result as { ai?: { calls?: unknown } }).ai : null;
  const calls = ai && Array.isArray(ai.calls) ? ai.calls : [];
  return calls.filter((c): c is Record<string, unknown> => !!c && typeof c === "object").map((c) => ({
    model: String(c.resolvedModel || c.model || "unknown"),
    costUsd: typeof c.costUsd === "number" ? c.costUsd : null,
    input: typeof c.inputTokens === "number" ? c.inputTokens : typeof c.input === "number" ? c.input : null,
    output: typeof c.outputTokens === "number" ? c.outputTokens : typeof c.output === "number" ? c.output : null,
  }));
}

// ---------------------------------------------------------------------------
// Margin per plan: what each plan's subscribers paid vs what their builds cost (30 days)
// ---------------------------------------------------------------------------

export type PlanRow = { userId: string; tier: string; status: string; livemode: boolean };
export type PlanPayment = { userId: string; tier: string | null; cents: number };
export type PlanMargin = { tier: string; listCents: number | null; subscribers: number; revenueUsd: number; spendUsd: number; marginUsd: number; marginPct: number | null; spendPerSubscriberUsd: number | null };

export function planMargins(i: { tiers: readonly string[]; plans: PlanRow[]; payments: PlanPayment[]; spend: Map<string, number>; listCents: Record<string, number | undefined> }): PlanMargin[] {
  return i.tiers.map((tier) => {
    const subs = i.plans.filter((p) => p.tier === tier && p.livemode && (p.status === "active" || p.status === "trialing" || p.status === "past_due"));
    const ids = new Set(subs.map((s) => s.userId));
    const revenueUsd = i.payments.filter((p) => p.tier === tier).reduce((a, p) => a + p.cents, 0) / 100;
    const spendUsd = [...ids].reduce((a, id) => a + (i.spend.get(id) ?? 0), 0);
    const marginUsd = revenueUsd - spendUsd;
    const lc = i.listCents[tier];
    return { tier, listCents: typeof lc === "number" && lc > 0 ? lc : null, subscribers: subs.length, revenueUsd, spendUsd, marginUsd, marginPct: revenueUsd > 0 ? marginUsd / revenueUsd : null, spendPerSubscriberUsd: subs.length ? spendUsd / subs.length : null };
  });
}

// ---------------------------------------------------------------------------
// Anomalies and alerts
// ---------------------------------------------------------------------------

export type CostFlag = { level: "red" | "amber"; code: string; text: string; userId?: string; buildId?: string };

/**
 * Relative rules only (no fixed dollar thresholds unless the owner set one):
 *  - a user's last-24 h spend is at least 3x their own 30-day daily mean and above the 95th percentile of users' 24 h spend
 *  - a single build costs more than 5x the 30-day median build cost (at least 20 priced builds in the window)
 *  - the owner's alert thresholds (platform / per user, 24 h), when set
 */
export function costAnomalies(i: { users: UserSpend[]; builds: (CostBuild & { id: string })[]; caps: CostCaps; platformTodayUsd: number; now: Date }): CostFlag[] {
  const out: CostFlag[] = [];
  const pct = (xs: number[], p: number) => { if (!xs.length) return 0; const s = [...xs].sort((a, b) => a - b); return s[Math.min(s.length - 1, Math.floor((p / 100) * s.length))]; };
  const p95 = pct(i.users.map((u) => u.d1), 95);
  for (const u of i.users) {
    if (u.d1 > 0 && u.d30 > u.d1 && u.d1 >= 3 * ((u.d30 - u.d1) / 29) && u.d1 >= p95 && i.users.length >= 5) out.push({ level: "amber", code: "user_spike", userId: u.userId, text: `24 h AI spend $${u.d1.toFixed(2)} is ${(u.d1 / Math.max(1e-9, (u.d30 - u.d1) / 29)).toFixed(1)}x this account's usual day.` });
    if (i.caps.alertUserDailyUsd > 0 && u.d1 >= i.caps.alertUserDailyUsd) out.push({ level: "red", code: "user_alert", userId: u.userId, text: `24 h AI spend $${u.d1.toFixed(2)} is over the per-account alert ($${i.caps.alertUserDailyUsd}).` });
  }
  const priced = i.builds.filter((b) => b.costUsd > 0);
  if (priced.length >= 20) {
    const med = pct(priced.map((b) => b.costUsd), 50);
    for (const b of priced) if (med > 0 && b.costUsd > 5 * med && i.now.getTime() - b.createdAt.getTime() < 7 * 86_400_000) out.push({ level: "amber", code: "build_outlier", buildId: b.id, userId: b.userId, text: `Build cost $${b.costUsd.toFixed(3)}, over 5x the median ($${med.toFixed(3)}).` });
  }
  if (i.caps.alertPlatformDailyUsd > 0 && i.platformTodayUsd >= i.caps.alertPlatformDailyUsd) out.push({ level: "red", code: "platform_alert", text: `AI spend today $${i.platformTodayUsd.toFixed(2)} is over the platform alert ($${i.caps.alertPlatformDailyUsd}).` });
  if (i.caps.platformDailyCapUsd > 0 && i.platformTodayUsd >= i.caps.platformDailyCapUsd) out.push({ level: "red", code: "platform_cap", text: `The platform daily cap ($${i.caps.platformDailyCapUsd}) is reached: new builds are refused until midnight UTC.` });
  return out.slice(0, 50);
}
