const CAP = 2000;

function refusedReason(r: { status: string; errorCode: string | null; error: string | null; result: unknown }): string {
  if (r.status !== "failed") return "";
  const res = r.result as ModBuildResult | null;
  const block = res?.safety?.findings?.find((f) => f.severity === "block");
  if (r.errorCode === "refused") return block ? `${block.rule}: ${block.message}` : r.error ?? "refused";
  return r.errorCode ? `${r.errorCode}${r.error ? `: ${r.error}` : ""}` : r.error ?? "";
}

/** Builds: searchable, filterable list; each row opens the build detail with the actions. */
export default async function CyrusAdminBuilds({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("builds");
  const sp = await searchParams;
  const f = parseBuildFilter(sp);
  const now = new Date();
  const userIds = f.q && f.q.length >= 3 ? (await db.user.findMany({ where: { email: { contains: f.q, mode: "insensitive" } }, select: { id: true }, take: 50 })).map((u) => u.id) : [];
  const rows = await cyrusDb.modBuild.findMany({
    where: buildWhere(f, now, userIds) as never,
    select: { ...LITE_SELECT, mcVersion: true, pluginName: true, version: true, prompt: true, changeRequest: true, error: true, result: true, baseBuildId: true },
    orderBy: { createdAt: "desc" },
    take: CAP,
  });
  const holds = await holdsFor(rows.map((r) => r.id));
  const emails = await emailMap(rows.map((r) => r.userId));
  const all = rows
    .map((r) => ({ r, lite: toLite(r, holds.get(r.id)?.model) }))
    // q / outcome / model / date are already applied in SQL; the game is derived, so filter it here.
    .filter(({ lite }) => matchBuild({ ...lite }, { ...f, q: "", outcome: "", model: "" }, now));
  const pages = Math.max(1, Math.ceil(all.length / BUILD_PAGE_SIZE));
  const page = Math.min(f.page, pages);
  const shown = all.slice((page - 1) * BUILD_PAGE_SIZE, page * BUILD_PAGE_SIZE);
  const sel = "input w-full text-sm sm:w-auto";

  return (
    <div>
      <Flash sp={sp} />
      <Section title="Builds" sub={`${n(all.length)} build(s) match${rows.length >= CAP ? ` (first ${CAP} searched; narrow the filter)` : ""}. Search by build id, plugin name, prompt text or customer email.`}>
        <form method="get" className="mb-4 grid gap-2 sm:flex sm:flex-wrap sm:items-end">
          <input name="q" defaultValue={f.q} placeholder="Search id, plugin, prompt, email" className="input w-full text-sm sm:w-72" aria-label="Search" />
          <select name="outcome" defaultValue={f.outcome} className={sel} aria-label="Outcome">
            <option value="">Any outcome</option>
            {BUILD_OUTCOMES.map((o) => <option key={o} value={o}>{o}</option>)}
          </select>
          <select name="model" defaultValue={f.model} className={sel} aria-label="Model">
            <option value="">Any model</option>
            {CYRUS_MODELS.map((m) => <option key={m.id} value={m.id}>{m.name}</option>)}
          </select>
          <select name="game" defaultValue={f.game} className={sel} aria-label="Game">
            <option value="">Any game</option>
            {CYRUS_GAMES.map((g) => <option key={g.id} value={g.id}>{g.name}</option>)}
          </select>
          <select name="days" defaultValue={String(f.days)} className={sel} aria-label="Period">
            {[1, 7, 30, 90, 365].map((d) => <option key={d} value={d}>Last {d === 1 ? "24 h" : `${d} days`}</option>)}
          </select>
          <button className="btn-primary text-sm">Filter</button>
          {filterQuery(f, { page: 1 }) ? <Link href="/admin/cyrus/builds" className="btn-ghost text-sm">Clear</Link> : null}
        </form>
        {shown.length === 0 ? <Empty>{rows.length === 0 && !f.q && !f.outcome && !f.model && !f.game ? "No Cyrus builds in this period yet." : "No builds match this filter."}</Empty> : (
          <TableWrap>
            <table className="w-full text-sm">
              <thead><tr className={thCls}><th>When</th><th>Customer</th><th>Game · version</th><th>Mod</th><th>Model</th><th>Status</th><th className="text-right">AI cost</th><th className="text-right">Tokens</th><th className="text-right">Time</th><th>Flight</th><th>Refused / error</th></tr></thead>
              <tbody>
                {shown.map(({ r, lite }) => {
                  const h = holds.get(r.id);
                  const o = buildOutcome(r);
                  return (
                    <tr key={r.id} className={tdRow}>
                      <td className="whitespace-nowrap"><Link className="font-mono text-xs underline decoration-white/20 underline-offset-2" href={`/admin/cyrus/builds/${r.id}`}>{r.id}</Link><div className="text-xs text-slate-500">{when(r.createdAt)}</div></td>
                      <td className="max-w-[200px] truncate"><UserLink id={r.userId} email={emails.get(r.userId)} /></td>
                      <td className="whitespace-nowrap">{lite.game} · {r.mcVersion}</td>
                      <td className="max-w-[220px]"><div className="truncate">{r.pluginName ?? "–"}{r.version ? ` v${r.version}` : ""}</div><div className="truncate text-xs text-slate-500" title={r.changeRequest || r.prompt}>{r.baseBuildId ? "change: " : ""}{(r.changeRequest || r.prompt).slice(0, 90)}</div></td>
                      <td className="capitalize">{lite.model}</td>
                      <td><OutcomeBadge outcome={o} />{o === "running" ? <div className="text-xs text-slate-500">{r.status}</div> : null}</td>
                      <td className="text-right tabular-nums">{usd(r.costUsd, 3)}</td>
                      <td className="text-right tabular-nums">{h ? (h.status === "held" ? <span title="held while running">{n(h.amount)} held</span> : n(h.charged ?? 0)) : <span className="text-slate-500" title="not in the token economy">–</span>}</td>
                      <td className="text-right tabular-nums">{secs(r.durationMs)}</td>
                      <td className="whitespace-nowrap text-xs">{flightLabel(r.cyrus) ?? <span className="text-slate-500">–</span>}</td>
                      <td className="max-w-[260px] truncate text-xs text-slate-400" title={refusedReason(r)}>{refusedReason(r) || "–"}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </TableWrap>
        )}
        {pages > 1 ? (
          <div className="mt-3 flex items-center justify-between text-sm">
            {page > 1 ? <Link className="btn-secondary text-xs" href={`/admin/cyrus/builds${filterQuery(f, { page: page - 1 })}`}>Previous</Link> : <span />}
            <span className="text-xs text-slate-500">Page {page} of {pages}</span>
            {page < pages ? <Link className="btn-secondary text-xs" href={`/admin/cyrus/builds${filterQuery(f, { page: page + 1 })}`}>Next</Link> : <span />}
          </div>
        ) : null}
      </Section>
    </div>
  );
}
