/**
 * Route-handler guard for /api/admin/cyrus/** (r40). Same rule as the pages and the server actions, but returns null
 * instead of redirecting, so the route answers a plain 404: the real account, not impersonating, on the "modbuilder"
 * preview list, with the action's role area. Fails closed on any error.
 */
export async function cyrusAdminApiUser(action: import("./perms").CyrusAdminAction): Promise<HostUser | null> {
  try {
    const { CYRUS_ADMIN_ACTIONS } = await import("./perms");
    const host = getHost();
    const [real, cur] = await Promise.all([host.auth.realUser(), host.auth.currentUser()]);
    if (!real || !cur || real.id !== cur.id) return null;
    if (!host.access.canAccess(real.role, CYRUS_ADMIN_ACTIONS[action])) return null;
    if (!(await host.access.isPreviewUser(real, "modbuilder"))) return null;
    return real;
  } catch {
    return null;
  }
}
// Cyrus admin audit trail. Every write made from /admin/cyrus lands here, in the existing AuditLog
// table (no schema change): action `cyrus.admin.<action>`, category "cyrus_admin", target = what it
// was done to, detail = JSON { before, after, note }. The Audit tab lists these rows together with
// the older Cyrus admin actions written by /admin/cyrus-tokens and /admin/cyrus-mods.
import { getHost } from "../host";
import type { CyrusAdminAction } from "./perms";

export const CYRUS_AUDIT_CATEGORY = "cyrus_admin";
export const CYRUS_AUDIT_PREFIX = "cyrus.admin.";

/** Admin actions written by the older Cyrus admin pages (shown in the same list). */
export const LEGACY_CYRUS_ADMIN_ACTIONS = [
  "cyrus.tokens.grant",
  "cyrus.tokens.revoke",
  "cyrus.tokens.tier",
  "cyrus.tokens.settings",
  "cyrusmods.launch",
  "cyrusmods.report.hide",
  "cyrusmods.report.dismiss",
  "cyrusmods.page.hide",
  "cyrusmods.page.unhide",
  "cyrus.lifecycle.setting",
];

export type AuditDetail = { before?: unknown; after?: unknown; note?: string };

const MAX = 4000;

/** JSON for AuditLog.detail, trimmed so one row can never be huge. Pure. */
export function auditDetail(d: AuditDetail): string {
  const s = JSON.stringify({ before: d.before ?? null, after: d.after ?? null, ...(d.note ? { note: d.note.slice(0, 300) } : {}) });
  if (s.length <= MAX) return s;
  return JSON.stringify({ before: "(trimmed)", after: "(trimmed)", note: (d.note ?? "").slice(0, 300), size: s.length });
}

/** Read AuditLog.detail back (our JSON, or a legacy free-text detail). Pure. */
export function readAuditDetail(raw: string | null): AuditDetail & { text?: string } {
  if (!raw) return {};
  if (raw.startsWith("{")) {
    try {
      const v = JSON.parse(raw) as Record<string, unknown>;
      if (v && typeof v === "object" && ("before" in v || "after" in v)) return { before: v.before, after: v.after, note: typeof v.note === "string" ? v.note : undefined };
    } catch { /* legacy text */ }
  }
  return { text: raw };
}

export async function cyrusAudit(i: { actorId: string; action: CyrusAdminAction; target: string; before?: unknown; after?: unknown; note?: string }): Promise<void> {
  await getHost().audit
    .append({ userId: i.actorId, action: CYRUS_AUDIT_PREFIX + i.action, category: CYRUS_AUDIT_CATEGORY, target: i.target.slice(0, 200), detail: auditDetail(i) })
    .catch((e) => console.error("[cyrus-admin] audit write failed", i.action, (e as Error).message));
}

