/** The game a build was for. ModBuild is the Minecraft build service's table; a future game id in the meta wins. */
export function gameOfBuild(row: Pick<ModBuild, "cyrus">): string {
  const g = row.cyrus && typeof row.cyrus === "object" && !Array.isArray(row.cyrus) ? (row.cyrus as Record<string, unknown>).game : null;
  return typeof g === "string" && /^[a-z0-9]{2,20}$/.test(g) ? g : "minecraft";
}

/** The Cyrus model of a build: the one picked (meta), else the token hold's model, else "auto" (service routing). */
export function modelOfBuild(row: Pick<ModBuild, "cyrus">, holdModel?: string | null): string {
  return readCyrusMeta(row.cyrus).model ?? holdModel ?? "auto";
}

export const LITE_SELECT = { id: true, userId: true, status: true, errorCode: true, costUsd: true, durationMs: true, createdAt: true, cyrus: true } as const;

export function toLite(row: Pick<ModBuild, "id" | "userId" | "status" | "errorCode" | "costUsd" | "durationMs" | "createdAt" | "cyrus">, holdModel?: string | null): BuildLite {
  return { id: row.id, userId: row.userId, status: row.status, errorCode: row.errorCode, costUsd: row.costUsd || 0, durationMs: row.durationMs, createdAt: row.createdAt, model: modelOfBuild(row, holdModel), game: gameOfBuild(row) };
}

export async function emailMap(ids: string[]): Promise<Map<string, string>> {
  const uniq = [...new Set(ids.filter(Boolean))];
  if (!uniq.length) return new Map();
  const users = await getHost().users.emails(uniq);
  return new Map(users.map((u) => [u.id, u.email]));
}

export async function holdsFor(buildIds: string[]) {
  if (!buildIds.length) return new Map<string, { model: string; amount: number; status: string; charged: number | null; costUsd: number | null }>();
  const rows = await db.cyrusTokenReservation.findMany({ where: { buildId: { in: buildIds } }, select: { buildId: true, model: true, amount: true, status: true, charged: true, costUsd: true } });
  return new Map(rows.map((r) => [r.buildId, r]));
}
