export type SettingType = "bool" | "int" | "number" | "enum" | "emails" | "text" | "json";

export type CyrusSettingDef = {
  key: string;
  label: string;
  description: string;
  type: SettingType;
  default: string;
  options?: string[];
  min?: number;
  max?: number;
  group: "launch" | "safety" | "games" | "lifecycle" | "tokens" | "features" | "kill" | "cost" | "storage";
  /** Branch whose code reads it ("base" = already on feature/cyrus-v6). */
  owner: "base" | "admin" | "lifecycle" | "capabilities";
  /** Edited on another screen (link) instead of inline here. */
  editAt?: string;
  /** Flipping it ON affects customers or money: the form asks for a confirm. */
  risky?: boolean;
};

const tokenRange: Record<string, [number, number]> = {
  cyrus_tok_tokens_per_usd: [1, 100000],
  cyrus_tok_mult_katara: [0.1, 20],
  cyrus_tok_mult_saka: [0.1, 20],
  cyrus_tok_mult_yakko: [0.1, 20],
  cyrus_tok_failed_charge_pct: [0, 100],
};

function tokenDef(k: (typeof TOKEN_SETTING_KEYS)[number]): CyrusSettingDef {
  const d = CYRUS_TOKEN_DEFAULTS[k];
  const bool = d === "true" || d === "false";
  const json = k === "cyrus_tok_reserve_table";
  const price = /^cyrus_tok_price_/.test(k) || k in TOKEN_ENUMS;
  const num = !bool && !json && !price;
  const r = tokenRange[k];
  return {
    key: k,
    label: k.replace(/^cyrus_tok_/, "").replace(/_/g, " "),
    description: `${(TOKEN_PLACEHOLDER_KEYS as readonly string[]).includes(k) ? "PLACEHOLDER default, pending the owner's decision. " : ""}${k in TOKEN_ENUMS ? `One of: ${(TOKEN_ENUMS as Record<string, readonly string[]>)[k].join(", ")}. ` : ""}Token economy setting (docs: "Cyrus token economy"). A blank or bad value falls back to the default, never to 0.`,
    type: bool ? "bool" : json ? "json" : price ? "text" : /mult_|per_usd$|pct$/.test(k) ? "number" : "int",
    default: d,
    ...(num ? { min: r?.[0] ?? 0, max: r?.[1] ?? 1_000_000 } : {}),
    group: "tokens",
    owner: "base",
    ...(json || price ? { editAt: "/admin/cyrus-tokens" } : {}),
    // r40: half of the launch pair (with cyrus_studio_public_enabled): only the pair switch on Flags may change it
    ...(k === "cyrus_tok_live" ? { editAt: "/admin/cyrus/flags#launch" } : {}),
    risky: k === "cyrus_tok_live" || k === "cyrus_tok_enforce",
  };
}

