const DAY = 86_400_000;
const meta = (m: unknown) => (m && typeof m === "object" && !Array.isArray(m) ? (m as Record<string, unknown>) : {});

/** Cyrus r40: AI spend per model and per account, spend caps and alerts, margin per plan, anomaly flags. */
export default async function CyrusCost({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("cost");
  const me = (await realUser())!;
  const sp = await searchParams;
  const now = new Date();
  const since = new Date(now.getTime() - 30 * DAY);
  const [builds, stored, plans, planPays, cfg] = await Promise.all([
    cyrusDb.modBuild.findMany({ where: { createdAt: { gt: since } }, select: { id: true, userId: true, costUsd: true, createdAt: true, result: true }, orderBy: { createdAt: "desc" }, take: 5000 }),
    db.setting.findMany({ where: { key: { in: Object.values(COST_SETTINGS) } } }),
    cyrusDb.cyrusPlan.findMany({ select: { userId: true, tier: true, status: true, livemode: true }, take: 10000 }),
    cyrusDb.cyrusTokenLedger.findMany({ where: { kind: "purchase", source: "plan", createdAt: { gt: since } }, select: { userId: true, meta: true }, take: 20000 }),
    loadTokenConfig(),
  ]);
  const caps = parseCostCaps(Object.fromEntries(stored.map((s) => [s.key, s.value])));
  const lite = builds.map((b) => ({ id: b.id, userId: b.userId, costUsd: b.costUsd || 0, createdAt: b.createdAt }));
  const users = spendByUser(lite, now);
  const models = spendByModel(builds.flatMap((b) => callsOfResult(b.result)));
  const platformTodayUsd = lite.filter((b) => b.createdAt >= utcDayStart(now)).reduce((a, b) => a + b.costUsd, 0);
  const total30 = lite.reduce((a, b) => a + b.costUsd, 0);
  const flags = costAnomalies({ users, builds: lite, caps, platformTodayUsd, now });
  const payments = planPays.map((p) => { const m = meta(p.meta); return m.livemode === false ? null : { userId: p.userId, tier: typeof m.tier === "string" ? m.tier : null, cents: typeof m.amountPaid === "number" ? m.amountPaid : 0 }; }).filter((x): x is { userId: string; tier: string | null; cents: number } => !!x);
  const margins = planMargins({ tiers: PLAN_TIERS, plans, payments, spend: new Map(users.map((u) => [u.userId, u.d30])), listCents: cfg.plan.cents });
  const top = users.slice(0, 25);
  const emails = await emailMap([...top.map((u) => u.userId), ...flags.map((f) => f.userId ?? "")]);
  const canSet = canCyrusAdmin(me.role, "setting.set");

  return (
    <div>
