// Cyrus token economy: the pure rules (no DB, no clock unless passed in, no network).
// Unit-tested in test/cyrus-tokens-economy.test.ts. Client-safe.
import { estimate } from "../estimate";
import type { CyrusModelId } from "../models";
import type { Complexity, PlanTier, TokenConfig, TokenTier } from "./config";

const DAY = 86_400_000;
export const round5 = (n: number) => Math.round(n / 5) * 5;
const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n));

// ---------------------------------------------------------------------------
// Models per tier
// ---------------------------------------------------------------------------

export const TIER_RANK: Record<TokenTier, number> = { free: 0, katara: 1, saka: 2, all: 3 };
export const TIER_MODELS: Record<TokenTier, CyrusModelId[]> = {
  free: ["katara"],
  katara: ["katara"],
  saka: ["katara", "saka"],
  all: ["katara", "saka", "yakko"],
};
export const TIER_LABEL: Record<TokenTier, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "All models" };

export const modelsFor = (tier: TokenTier) => TIER_MODELS[tier];
export const canUseModel = (tier: TokenTier, model: CyrusModelId) => TIER_MODELS[tier].includes(model);
/** The cheapest tier that unlocks a model. */
export const tierForModel = (model: CyrusModelId): PlanTier => (model === "yakko" ? "all" : model === "saka" ? "saka" : "katara");
export const maxTier = (a: TokenTier, b: TokenTier): TokenTier => (TIER_RANK[a] >= TIER_RANK[b] ? a : b);
/** Best model a tier may use by default when the request names none. */
export const defaultModelFor = (tier: TokenTier): CyrusModelId => (canUseModel(tier, "saka") ? "saka" : "katara");

export type PlanState = {
  tier: string;
  status: string;
  currentPeriodEnd: Date | null;
  endedAt?: Date | null;
} | null;

/**
 * The account's model entitlement right now. A plan entitles its PAID tier while the paid
 * period runs (also after cancel, until the period ends), plus `pastDueGraceDays` while
 * Stripe retries a failed renewal. An admin override can only raise it.
 */
export function effectiveTier(input: { plan: PlanState; override?: string | null; overrideUntil?: Date | null; now: Date; cfg: TokenConfig }): TokenTier {
  const { plan, now, cfg } = input;
  let tier: TokenTier = "free";
  if (plan && (plan.tier === "katara" || plan.tier === "saka" || plan.tier === "all") && plan.currentPeriodEnd) {
    const end = plan.currentPeriodEnd.getTime();
    const ok =
      ["active", "trialing"].includes(plan.status) ? now.getTime() < end + DAY // a day of slack for webhook lag
      : plan.status === "past_due" ? now.getTime() < end + cfg.plan.pastDueGraceDays * DAY
      : plan.status === "canceled" ? now.getTime() < end
      : false; // incomplete, incomplete_expired, unpaid, paused
    if (ok) tier = plan.tier;
  }
  const o = input.override;
  if ((o === "katara" || o === "saka" || o === "all") && (!input.overrideUntil || input.overrideUntil.getTime() > now.getTime())) tier = maxTier(tier, o);
  return tier;
}

// ---------------------------------------------------------------------------
// Game-server grants
// ---------------------------------------------------------------------------

function perMonth(kind: "initial" | "renew", monthlyCents: number, cfg: TokenConfig): number {
  if (!(monthlyCents > 0)) return 0;
  const r = cfg.grant[kind];
  return Math.round(clamp(round5(r.base + r.perUsd * (monthlyCents / 100)), r.min, r.max));
}

