/** Stacked bars per day (succeeded / failed / refused / cancelled / running). Pure SVG, scales to its box. */
export function DayBars({ days }: { days: { day: string; succeeded: number; failed: number; refused: number; cancelled: number; running: number; total: number }[] }) {
  const max = Math.max(1, ...days.map((d) => d.total));
  const W = 720;
  const H = 160;
  const bw = W / days.length;
  const parts: [keyof (typeof days)[number], string][] = [["succeeded", "var(--adm-green, #3fd89a)"], ["failed", "var(--adm-red, #f0607a)"], ["refused", "var(--adm-amber, #f2b64b)"], ["cancelled", "var(--adm-faint, #5f6a8c)"], ["running", "var(--adm-blue, #3b6be8)"]];
  const total = days.reduce((a, d) => a + d.total, 0);
  return (
    <div>
      <svg viewBox={`0 0 ${W} ${H + 18}`} className="h-auto w-full" role="img" aria-label={`Builds per day, ${total} in ${days.length} days`}>
        <line x1="0" x2={W} y1={H} y2={H} stroke="currentColor" strokeOpacity="0.15" />
        {days.map((d, i) => {
          let y = H;
          return (
            <g key={d.day}>
              <title>{`${d.day}: ${d.total} builds (${d.succeeded} ok, ${d.failed} failed, ${d.refused} refused, ${d.cancelled} cancelled, ${d.running} running)`}</title>
              {parts.map(([k, color]) => {
                const v = d[k] as number;
                if (!v) return null;
                const h = (v / max) * (H - 6);
                y -= h;
                return <rect key={String(k)} x={i * bw + bw * 0.15} y={y} width={bw * 0.7} height={h} rx="2" fill={color} />;
              })}
              {(i === 0 || i === days.length - 1 || i % 7 === 0) && (
                <text x={i * bw + bw / 2} y={H + 14} textAnchor={i === 0 ? "start" : i === days.length - 1 ? "end" : "middle"} fontSize="11" fill="currentColor" fillOpacity="0.5">{d.day.slice(5)}</text>
              )}
            </g>
          );
        })}
      </svg>
