async function serviceUsage(id: string): Promise<{ stages: [string, StageUsage][]; autofix: number; savedRepairs: number } | null> {
  try {
    const s = (await svcGet(id)) as unknown as { usage?: { stages?: Record<string, StageUsage>; autofix?: number; savedRepairs?: number } } | null;
