// Cyrus admin: the maths behind the Overview, Builds and Users tabs. PURE (no DB, no clock unless
// passed in, no network) and client-safe. Unit-tested in test/cyrus-admin.test.ts.
//
// Everything here works on rows the pages already read from the DB (ModBuild, CyrusTokenReservation,
// CyrusTokenLedger), so a number on screen is always a real count or sum, never an estimate.

const DAY = 86_400_000;

// ---------------------------------------------------------------------------
// Build outcome
// ---------------------------------------------------------------------------

export type BuildOutcome = "succeeded" | "failed" | "refused" | "cancelled" | "running";
export const BUILD_OUTCOMES: BuildOutcome[] = ["succeeded", "failed", "refused", "cancelled", "running"];

/** One build as the admin maths sees it. `model` / `game` already resolved by the caller. */
export type BuildLite = {
  id: string;
  userId: string;
  status: string;
  errorCode: string | null;
  costUsd: number;
  durationMs: number | null;
  createdAt: Date;
  model: string | null;
  game: string;
};

/** A refusal (safety) and a cancel are failures in the DB; the admin counts them apart. */
export function buildOutcome(b: { status: string; errorCode: string | null }): BuildOutcome {
  if (b.status === "succeeded") return "succeeded";
  if (b.status !== "failed") return "running";
  if (b.errorCode === "refused") return "refused";
  if (b.errorCode === "cancelled" || b.errorCode === "admin_cancelled") return "cancelled";
  return "failed";
}

// ---------------------------------------------------------------------------
// Statistics
// ---------------------------------------------------------------------------

/** Nearest-rank percentile (p in 0..100). null for an empty list. */
export function percentile(values: number[], p: number): number | null {
  const v = values.filter((x) => Number.isFinite(x)).sort((a, b) => a - b);
  if (!v.length) return null;
  const rank = Math.ceil((Math.min(100, Math.max(0, p)) / 100) * v.length);
  return v[Math.max(0, rank - 1)];
}

export function mean(values: number[]): number | null {
  const v = values.filter((x) => Number.isFinite(x));
  return v.length ? v.reduce((a, x) => a + x, 0) / v.length : null;
}

