export type BuildFilter = {
  q: string;
  outcome: BuildOutcome | "";
  model: string;
  game: string;
  days: number;
  page: number;
};

export const BUILD_PAGE_SIZE = 50;
const DAY_CHOICES = [1, 7, 30, 90, 365];

/** Parse untrusted search params into a safe filter (bad values fall back to "no filter"). */
export function parseBuildFilter(sp: Record<string, string | string[] | undefined>): BuildFilter {
  const one = (k: string) => {
    const v = sp[k];
    return (Array.isArray(v) ? v[0] : v ?? "").trim();
  };
  const outcome = one("outcome");
  const model = one("model").toLowerCase();
  const game = one("game").toLowerCase();
  const days = Number(one("days"));
  const page = Math.floor(Number(one("page")));
  return {
    q: one("q").slice(0, 120),
    outcome: (BUILD_OUTCOMES as string[]).includes(outcome) ? (outcome as BuildOutcome) : "",
    model: /^[a-z0-9-]{1,20}$/.test(model) ? model : "",
    game: /^[a-z0-9-]{1,30}$/.test(game) ? game : "",
    days: DAY_CHOICES.includes(days) ? days : 30,
    page: Number.isFinite(page) && page > 0 ? Math.min(page, 1000) : 1,
  };
}

/** Prisma `where` for the DB-side part of the filter (outcome + date + id/prompt/plugin search). */
export function buildWhere(f: BuildFilter, now: Date, userIds: string[] = []) {
  const and: Record<string, unknown>[] = [{ createdAt: { gt: new Date(now.getTime() - f.days * DAY) } }];
  if (f.outcome === "succeeded") and.push({ status: "succeeded" });
  else if (f.outcome === "running") and.push({ status: { notIn: ["succeeded", "failed"] } });
  else if (f.outcome === "refused") and.push({ status: "failed", errorCode: "refused" });
  else if (f.outcome === "cancelled") and.push({ status: "failed", errorCode: { in: ["cancelled", "admin_cancelled"] } });
  else if (f.outcome === "failed") and.push({ status: "failed", OR: [{ errorCode: null }, { errorCode: { notIn: ["refused", "cancelled", "admin_cancelled"] } }] });
  if (f.model) and.push({ cyrus: { path: ["model"], equals: f.model } });
  if (f.q) {
    const or: Record<string, unknown>[] = [
      { id: f.q },
      { pluginName: { contains: f.q, mode: "insensitive" } },
      { prompt: { contains: f.q, mode: "insensitive" } },
      { changeRequest: { contains: f.q, mode: "insensitive" } },
    ];
    if (userIds.length) or.push({ userId: { in: userIds } });
    and.push({ OR: or });
  }
  return { AND: and };
}

/** The same filter applied in memory (used for the game filter, which is derived, and in tests). */
export function matchBuild(b: BuildLite & { prompt?: string; pluginName?: string | null; email?: string | null }, f: BuildFilter, now: Date): boolean {
  if (b.createdAt.getTime() <= now.getTime() - f.days * DAY) return false;
  if (f.outcome && buildOutcome(b) !== f.outcome) return false;
  if (f.model && b.model !== f.model) return false;
  if (f.game && b.game !== f.game) return false;
  if (f.q) {
    const q = f.q.toLowerCase();
    const hay = [b.id, b.pluginName ?? "", b.prompt ?? "", b.email ?? ""].join("\n").toLowerCase();
    if (!hay.includes(q)) return false;
  }
  return true;
}

/** Query string for a filter (only non-default parts), for links and pagination. */
export function filterQuery(f: BuildFilter, patch: Partial<BuildFilter> = {}): string {
  const g = { ...f, ...patch };
  const p = new URLSearchParams();
  if (g.q) p.set("q", g.q);
  if (g.outcome) p.set("outcome", g.outcome);
  if (g.model) p.set("model", g.model);
  if (g.game) p.set("game", g.game);
  if (g.days !== 30) p.set("days", String(g.days));
  if (g.page > 1) p.set("page", String(g.page));
  const s = p.toString();
  return s ? `?${s}` : "";
