// Cyrus live code: the in-progress workspace of one of the user's running builds
// (src/main/** only, read-only, proxied from the build service's /live).
// `draft` + `from` ask only for the part of the file being written that the client hasn't seen.
export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  const empty = { live: false, status: o.build.status, files: [], draft: null };
  if (isTerminal(o.build.status)) return NextResponse.json(empty, { headers: { "Cache-Control": "no-store" } });
  const rl = checkRateLimit(`mb:live:${o.user.id}`, { max: 240, windowMs: 60_000 });
  if (!rl.ok) return NextResponse.json({ error: "Slow down a little and try again in a moment." }, { status: 429 });
  const u = new URL(req.url);
  const draft = u.searchParams.get("draft") || "";
  if (draft && (!/^src\/main\/(java|resources)\/[A-Za-z0-9_./-]{1,240}$/.test(draft) || draft.includes(".."))) return NextResponse.json({ error: "Bad path" }, { status: 400 });
  const from = Math.max(0, Math.min(2_000_000, parseInt(u.searchParams.get("from") || "0", 10) || 0));
  const seq = Math.max(0, Math.min(1_000_000, parseInt(u.searchParams.get("seq") || "0", 10) || 0));
  try {
    const live = await svcLive(o.build.id, draft || undefined, from, seq);
    return NextResponse.json(live ?? empty, { headers: { "Cache-Control": "no-store" } });
  } catch {
    return NextResponse.json({ error: "The builder is offline right now. Try again in a few minutes." }, { status: 503 });
  }
}

